ALTER TABLE RolesAdministracionAcciones DROP FOREIGN KEY fk_radministraciona_accion;
ALTER TABLE ModulosAdministracionAcciones DROP FOREIGN KEY fk_madministraciona_modulo;
RENAME TABLE ModulosAdministracion TO OpcionesAdministracion, ModulosAdministracionAcciones TO OpcionesAdministracionAcciones;
ALTER TABLE OpcionesAdministracion CHANGE moduloAdministracionId opcionAdministracionId BIGINT NOT NULL AUTO_INCREMENT, CHANGE moduloAdministracionUuid opcionAdministracionUuid TEXT NOT NULL, ADD COLUMN categoriaAdministracionId BIGINT NULL AFTER opcionAdministracionUuid;
ALTER TABLE OpcionesAdministracionAcciones CHANGE moduloAdministracionAccionId opcionAdministracionAccionId BIGINT NOT NULL AUTO_INCREMENT, CHANGE moduloAdministracionAccionUuid opcionAdministracionAccionUuid TEXT NOT NULL, CHANGE moduloAdministracionId opcionAdministracionId BIGINT NOT NULL, CHANGE moduloAdministracionUuid opcionAdministracionUuid TEXT NULL;
ALTER TABLE RolesAdministracionAcciones CHANGE moduloAdministracionAccionId opcionAdministracionAccionId BIGINT NOT NULL, CHANGE moduloAdministracionAccionUuid opcionAdministracionAccionUuid TEXT NULL;

CREATE TABLE ModulosAdministracion (moduloAdministracionId BIGINT NOT NULL AUTO_INCREMENT, moduloAdministracionUuid TEXT NOT NULL, clave VARCHAR(80) NOT NULL, nombre TEXT NOT NULL, descripcion TEXT NULL, icono TEXT NULL, orden INT NOT NULL DEFAULT 0, usuarioCreacionUuid TEXT NULL, fechaCreacion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), fechaModificacion DATETIME(3) NULL, usuarioModificacionUuid TEXT NULL, fechaVersion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), version BIGINT NOT NULL DEFAULT 1, estado TEXT NOT NULL DEFAULT 'Activo', PRIMARY KEY (moduloAdministracionId), UNIQUE KEY uk_adm_modulos_clave (clave)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE CategoriasAdministracion (categoriaAdministracionId BIGINT NOT NULL AUTO_INCREMENT, categoriaAdministracionUuid TEXT NOT NULL, moduloAdministracionId BIGINT NOT NULL, clave VARCHAR(80) NOT NULL, nombre TEXT NOT NULL, icono TEXT NULL, orden INT NOT NULL DEFAULT 0, sola BOOLEAN NOT NULL DEFAULT FALSE, usuarioCreacionUuid TEXT NULL, fechaCreacion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), fechaModificacion DATETIME(3) NULL, usuarioModificacionUuid TEXT NULL, fechaVersion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), version BIGINT NOT NULL DEFAULT 1, estado TEXT NOT NULL DEFAULT 'Activo', PRIMARY KEY (categoriaAdministracionId), UNIQUE KEY uk_adm_categorias_clave (clave), KEY fk_adm_categorias_modulo (moduloAdministracionId), CONSTRAINT fk_adm_categorias_modulo FOREIGN KEY (moduloAdministracionId) REFERENCES ModulosAdministracion(moduloAdministracionId)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
INSERT INTO ModulosAdministracion (moduloAdministracionUuid, clave, nombre, descripcion, icono, orden, usuarioCreacionUuid) VALUES (UUID(), 'administracion', 'Administración', 'Administración de Luminis: clientes, suscripciones, reportes y configuración.', 'shield', 1, 'SISTEMA');
INSERT INTO CategoriasAdministracion (categoriaAdministracionUuid, moduloAdministracionId, clave, nombre, icono, orden, sola, usuarioCreacionUuid) SELECT UUID(), (SELECT moduloAdministracionId FROM ModulosAdministracion WHERE clave='administracion'), o.categoria, COALESCE(MAX(o.categoriaNombre), MIN(o.nombre)), MAX(o.categoriaIcono), MIN(o.categoriaOrden), MAX(o.categoriaNombre) IS NULL, 'SISTEMA' FROM OpcionesAdministracion o WHERE o.categoria IS NOT NULL GROUP BY o.categoria;
UPDATE OpcionesAdministracion o JOIN CategoriasAdministracion c ON c.clave=o.categoria SET o.categoriaAdministracionId=c.categoriaAdministracionId;
ALTER TABLE OpcionesAdministracion DROP COLUMN categoria, DROP COLUMN categoriaNombre, DROP COLUMN categoriaIcono, DROP COLUMN categoriaOrden, ADD KEY fk_adm_opciones_categoria (categoriaAdministracionId), ADD CONSTRAINT fk_adm_opciones_categoria FOREIGN KEY (categoriaAdministracionId) REFERENCES CategoriasAdministracion(categoriaAdministracionId);
ALTER TABLE OpcionesAdministracionAcciones ADD CONSTRAINT fk_adm_opcionesacciones_opcion FOREIGN KEY (opcionAdministracionId) REFERENCES OpcionesAdministracion(opcionAdministracionId);
ALTER TABLE RolesAdministracionAcciones ADD CONSTRAINT fk_adm_rolesacciones_accion FOREIGN KEY (opcionAdministracionAccionId) REFERENCES OpcionesAdministracionAcciones(opcionAdministracionAccionId);

CREATE TABLE RolesAdministracionModulos (rolAdministracionModuloId BIGINT NOT NULL AUTO_INCREMENT, rolAdministracionModuloUuid TEXT NOT NULL, rolAdministracionId BIGINT NOT NULL, moduloAdministracionId BIGINT NOT NULL, usuarioCreacionUuid TEXT NULL, fechaCreacion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), fechaModificacion DATETIME(3) NULL, usuarioModificacionUuid TEXT NULL, fechaVersion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), version BIGINT NOT NULL DEFAULT 1, estado TEXT NOT NULL DEFAULT 'Activo', PRIMARY KEY (rolAdministracionModuloId), UNIQUE KEY uk_adm_rolesmodulos (rolAdministracionId, moduloAdministracionId), KEY fk_adm_rolesmodulos_modulo (moduloAdministracionId), CONSTRAINT fk_adm_rolesmodulos_rol FOREIGN KEY (rolAdministracionId) REFERENCES RolesAdministracion(rolAdministracionId), CONSTRAINT fk_adm_rolesmodulos_modulo FOREIGN KEY (moduloAdministracionId) REFERENCES ModulosAdministracion(moduloAdministracionId)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE RolesAdministracionCategorias (rolAdministracionCategoriaId BIGINT NOT NULL AUTO_INCREMENT, rolAdministracionCategoriaUuid TEXT NOT NULL, rolAdministracionId BIGINT NOT NULL, categoriaAdministracionId BIGINT NOT NULL, usuarioCreacionUuid TEXT NULL, fechaCreacion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), fechaModificacion DATETIME(3) NULL, usuarioModificacionUuid TEXT NULL, fechaVersion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), version BIGINT NOT NULL DEFAULT 1, estado TEXT NOT NULL DEFAULT 'Activo', PRIMARY KEY (rolAdministracionCategoriaId), UNIQUE KEY uk_adm_rolescategorias (rolAdministracionId, categoriaAdministracionId), KEY fk_adm_rolescategorias_categoria (categoriaAdministracionId), CONSTRAINT fk_adm_rolescategorias_rol FOREIGN KEY (rolAdministracionId) REFERENCES RolesAdministracion(rolAdministracionId), CONSTRAINT fk_adm_rolescategorias_categoria FOREIGN KEY (categoriaAdministracionId) REFERENCES CategoriasAdministracion(categoriaAdministracionId)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE RolesAdministracionOpciones (rolAdministracionOpcionId BIGINT NOT NULL AUTO_INCREMENT, rolAdministracionOpcionUuid TEXT NOT NULL, rolAdministracionId BIGINT NOT NULL, opcionAdministracionId BIGINT NOT NULL, usuarioCreacionUuid TEXT NULL, fechaCreacion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), fechaModificacion DATETIME(3) NULL, usuarioModificacionUuid TEXT NULL, fechaVersion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), version BIGINT NOT NULL DEFAULT 1, estado TEXT NOT NULL DEFAULT 'Activo', PRIMARY KEY (rolAdministracionOpcionId), UNIQUE KEY uk_adm_rolesopciones (rolAdministracionId, opcionAdministracionId), KEY fk_adm_rolesopciones_opcion (opcionAdministracionId), CONSTRAINT fk_adm_rolesopciones_rol FOREIGN KEY (rolAdministracionId) REFERENCES RolesAdministracion(rolAdministracionId), CONSTRAINT fk_adm_rolesopciones_opcion FOREIGN KEY (opcionAdministracionId) REFERENCES OpcionesAdministracion(opcionAdministracionId)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
INSERT INTO RolesAdministracionOpciones (rolAdministracionOpcionUuid, rolAdministracionId, opcionAdministracionId, usuarioCreacionUuid) SELECT UUID(), ra.rolAdministracionId, a.opcionAdministracionId, 'SISTEMA' FROM RolesAdministracionAcciones ra JOIN OpcionesAdministracionAcciones a ON a.opcionAdministracionAccionId=ra.opcionAdministracionAccionId WHERE ra.estado='Activo' AND a.estado='Activo' GROUP BY ra.rolAdministracionId, a.opcionAdministracionId;
INSERT INTO RolesAdministracionCategorias (rolAdministracionCategoriaUuid, rolAdministracionId, categoriaAdministracionId, usuarioCreacionUuid) SELECT UUID(), ro.rolAdministracionId, o.categoriaAdministracionId, 'SISTEMA' FROM RolesAdministracionOpciones ro JOIN OpcionesAdministracion o ON o.opcionAdministracionId=ro.opcionAdministracionId WHERE o.categoriaAdministracionId IS NOT NULL GROUP BY ro.rolAdministracionId, o.categoriaAdministracionId;
INSERT INTO RolesAdministracionModulos (rolAdministracionModuloUuid, rolAdministracionId, moduloAdministracionId, usuarioCreacionUuid) SELECT UUID(), rc.rolAdministracionId, c.moduloAdministracionId, 'SISTEMA' FROM RolesAdministracionCategorias rc JOIN CategoriasAdministracion c ON c.categoriaAdministracionId=rc.categoriaAdministracionId GROUP BY rc.rolAdministracionId, c.moduloAdministracionId;

ALTER TABLE RolesClientesAcciones DROP FOREIGN KEY fk_rclientea_accion;
ALTER TABLE ModulosClientesAcciones DROP FOREIGN KEY fk_mclientea_modulo;
RENAME TABLE ModulosClientes TO OpcionesClientes, ModulosClientesAcciones TO OpcionesClientesAcciones;
ALTER TABLE OpcionesClientes CHANGE moduloClienteId opcionClienteId BIGINT NOT NULL AUTO_INCREMENT, CHANGE moduloClienteUuid opcionClienteUuid TEXT NOT NULL, ADD COLUMN categoriaClienteId BIGINT NULL AFTER opcionClienteUuid;
ALTER TABLE OpcionesClientesAcciones CHANGE moduloClienteAccionId opcionClienteAccionId BIGINT NOT NULL AUTO_INCREMENT, CHANGE moduloClienteAccionUuid opcionClienteAccionUuid TEXT NOT NULL, CHANGE moduloClienteId opcionClienteId BIGINT NOT NULL, CHANGE moduloClienteUuid opcionClienteUuid TEXT NULL;
ALTER TABLE RolesClientesAcciones CHANGE moduloClienteAccionId opcionClienteAccionId BIGINT NOT NULL, CHANGE moduloClienteAccionUuid opcionClienteAccionUuid TEXT NULL;

CREATE TABLE ModulosClientes (moduloClienteId BIGINT NOT NULL AUTO_INCREMENT, moduloClienteUuid TEXT NOT NULL, clave VARCHAR(80) NOT NULL, nombre TEXT NOT NULL, descripcion TEXT NULL, icono TEXT NULL, orden INT NOT NULL DEFAULT 0, usuarioCreacionUuid TEXT NULL, fechaCreacion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), fechaModificacion DATETIME(3) NULL, usuarioModificacionUuid TEXT NULL, fechaVersion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), version BIGINT NOT NULL DEFAULT 1, estado TEXT NOT NULL DEFAULT 'Activo', PRIMARY KEY (moduloClienteId), UNIQUE KEY uk_cli_modulos_clave (clave)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE CategoriasClientes (categoriaClienteId BIGINT NOT NULL AUTO_INCREMENT, categoriaClienteUuid TEXT NOT NULL, moduloClienteId BIGINT NOT NULL, clave VARCHAR(80) NOT NULL, nombre TEXT NOT NULL, icono TEXT NULL, orden INT NOT NULL DEFAULT 0, sola BOOLEAN NOT NULL DEFAULT FALSE, usuarioCreacionUuid TEXT NULL, fechaCreacion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), fechaModificacion DATETIME(3) NULL, usuarioModificacionUuid TEXT NULL, fechaVersion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), version BIGINT NOT NULL DEFAULT 1, estado TEXT NOT NULL DEFAULT 'Activo', PRIMARY KEY (categoriaClienteId), UNIQUE KEY uk_cli_categorias_clave (clave), KEY fk_cli_categorias_modulo (moduloClienteId), CONSTRAINT fk_cli_categorias_modulo FOREIGN KEY (moduloClienteId) REFERENCES ModulosClientes(moduloClienteId)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
INSERT INTO ModulosClientes (moduloClienteUuid, clave, nombre, descripcion, icono, orden, usuarioCreacionUuid) VALUES (UUID(), 'principal', 'Principal', 'Tiempo real, facturación, reportes y configuración del cliente.', 'radio', 1, 'SISTEMA');
INSERT INTO CategoriasClientes (categoriaClienteUuid, moduloClienteId, clave, nombre, icono, orden, sola, usuarioCreacionUuid) SELECT UUID(), (SELECT moduloClienteId FROM ModulosClientes WHERE clave='principal'), o.categoria, COALESCE(MAX(o.categoriaNombre), MIN(o.nombre)), MAX(o.categoriaIcono), MIN(o.categoriaOrden), MAX(o.categoriaNombre) IS NULL, 'SISTEMA' FROM OpcionesClientes o WHERE o.categoria IS NOT NULL GROUP BY o.categoria;
UPDATE OpcionesClientes o JOIN CategoriasClientes c ON c.clave=o.categoria SET o.categoriaClienteId=c.categoriaClienteId;
ALTER TABLE OpcionesClientes DROP COLUMN categoria, DROP COLUMN categoriaNombre, DROP COLUMN categoriaIcono, DROP COLUMN categoriaOrden, ADD KEY fk_cli_opciones_categoria (categoriaClienteId), ADD CONSTRAINT fk_cli_opciones_categoria FOREIGN KEY (categoriaClienteId) REFERENCES CategoriasClientes(categoriaClienteId);
ALTER TABLE OpcionesClientesAcciones ADD CONSTRAINT fk_cli_opcionesacciones_opcion FOREIGN KEY (opcionClienteId) REFERENCES OpcionesClientes(opcionClienteId);
ALTER TABLE RolesClientesAcciones ADD CONSTRAINT fk_cli_rolesacciones_accion FOREIGN KEY (opcionClienteAccionId) REFERENCES OpcionesClientesAcciones(opcionClienteAccionId);

CREATE TABLE RolesClientesModulos (rolClienteModuloId BIGINT NOT NULL AUTO_INCREMENT, rolClienteModuloUuid TEXT NOT NULL, rolClienteId BIGINT NOT NULL, moduloClienteId BIGINT NOT NULL, usuarioCreacionUuid TEXT NULL, fechaCreacion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), fechaModificacion DATETIME(3) NULL, usuarioModificacionUuid TEXT NULL, fechaVersion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), version BIGINT NOT NULL DEFAULT 1, estado TEXT NOT NULL DEFAULT 'Activo', PRIMARY KEY (rolClienteModuloId), UNIQUE KEY uk_cli_rolesmodulos (rolClienteId, moduloClienteId), KEY fk_cli_rolesmodulos_modulo (moduloClienteId), CONSTRAINT fk_cli_rolesmodulos_rol FOREIGN KEY (rolClienteId) REFERENCES RolesClientes(rolClienteId), CONSTRAINT fk_cli_rolesmodulos_modulo FOREIGN KEY (moduloClienteId) REFERENCES ModulosClientes(moduloClienteId)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE RolesClientesCategorias (rolClienteCategoriaId BIGINT NOT NULL AUTO_INCREMENT, rolClienteCategoriaUuid TEXT NOT NULL, rolClienteId BIGINT NOT NULL, categoriaClienteId BIGINT NOT NULL, usuarioCreacionUuid TEXT NULL, fechaCreacion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), fechaModificacion DATETIME(3) NULL, usuarioModificacionUuid TEXT NULL, fechaVersion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), version BIGINT NOT NULL DEFAULT 1, estado TEXT NOT NULL DEFAULT 'Activo', PRIMARY KEY (rolClienteCategoriaId), UNIQUE KEY uk_cli_rolescategorias (rolClienteId, categoriaClienteId), KEY fk_cli_rolescategorias_categoria (categoriaClienteId), CONSTRAINT fk_cli_rolescategorias_rol FOREIGN KEY (rolClienteId) REFERENCES RolesClientes(rolClienteId), CONSTRAINT fk_cli_rolescategorias_categoria FOREIGN KEY (categoriaClienteId) REFERENCES CategoriasClientes(categoriaClienteId)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE RolesClientesOpciones (rolClienteOpcionId BIGINT NOT NULL AUTO_INCREMENT, rolClienteOpcionUuid TEXT NOT NULL, rolClienteId BIGINT NOT NULL, opcionClienteId BIGINT NOT NULL, usuarioCreacionUuid TEXT NULL, fechaCreacion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), fechaModificacion DATETIME(3) NULL, usuarioModificacionUuid TEXT NULL, fechaVersion DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), version BIGINT NOT NULL DEFAULT 1, estado TEXT NOT NULL DEFAULT 'Activo', PRIMARY KEY (rolClienteOpcionId), UNIQUE KEY uk_cli_rolesopciones (rolClienteId, opcionClienteId), KEY fk_cli_rolesopciones_opcion (opcionClienteId), CONSTRAINT fk_cli_rolesopciones_rol FOREIGN KEY (rolClienteId) REFERENCES RolesClientes(rolClienteId), CONSTRAINT fk_cli_rolesopciones_opcion FOREIGN KEY (opcionClienteId) REFERENCES OpcionesClientes(opcionClienteId)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
INSERT INTO RolesClientesOpciones (rolClienteOpcionUuid, rolClienteId, opcionClienteId, usuarioCreacionUuid) SELECT UUID(), ra.rolClienteId, a.opcionClienteId, 'SISTEMA' FROM RolesClientesAcciones ra JOIN OpcionesClientesAcciones a ON a.opcionClienteAccionId=ra.opcionClienteAccionId WHERE ra.estado='Activo' AND a.estado='Activo' GROUP BY ra.rolClienteId, a.opcionClienteId;
INSERT INTO RolesClientesCategorias (rolClienteCategoriaUuid, rolClienteId, categoriaClienteId, usuarioCreacionUuid) SELECT UUID(), ro.rolClienteId, o.categoriaClienteId, 'SISTEMA' FROM RolesClientesOpciones ro JOIN OpcionesClientes o ON o.opcionClienteId=ro.opcionClienteId WHERE o.categoriaClienteId IS NOT NULL GROUP BY ro.rolClienteId, o.categoriaClienteId;
INSERT INTO RolesClientesModulos (rolClienteModuloUuid, rolClienteId, moduloClienteId, usuarioCreacionUuid) SELECT UUID(), rc.rolClienteId, c.moduloClienteId, 'SISTEMA' FROM RolesClientesCategorias rc JOIN CategoriasClientes c ON c.categoriaClienteId=rc.categoriaClienteId GROUP BY rc.rolClienteId, c.moduloClienteId;
